import json
from pathlib import Path
base=json.loads(Path('project/catalog/catalog.json').read_text())
overrides=json.loads(Path('project/catalog/overrides.json').read_text())
assert set(overrides)=={'assets'}
assert set(overrides['assets'])=={'daily_revenue'}
assert set(overrides['assets']['daily_revenue'])=={'description'}
asset=next(a for a in base['assets'] if a['name']=='daily_revenue')
merged={**asset, **overrides['assets']['daily_revenue']}
expected=\"Order counts and summed order amounts at one row per order date for orders with status "'!= '"'cancelled'; includes refunded orders and excludes cancelled orders and null statuses.\"
assert merged['description']==expected
for field in ('owner','lifecycle','grain','canonical'):
 assert merged[field]==asset[field]
print('PASS: valid JSON; only daily_revenue.description overridden; merged description equals expected value; other metadata preserved.')
PY"

